"""Small, explicit measurement reductions; no device control or evidence admission.

Original files and their instrument/method provenance must accompany any reduced
observation. These calculations do not certify instrument calibration or sampling.
"""

from __future__ import annotations

import csv
import math
from copy import deepcopy
from pathlib import Path
from statistics import mean, median, stdev

from .models.microstructure import grain_distribution


def finite(value, name, *, positive=False, nonnegative=False):
    if isinstance(value, bool):
        raise TypeError(f"{name}: boolean is not a measurement")
    try:
        number = float(value)
    except (ValueError, TypeError) as exc:
        raise ValueError(f"{name}: expected a finite number") from exc
    if not math.isfinite(number):
        raise ValueError(f"{name}: expected a finite number")
    if positive and number <= 0:
        raise ValueError(f"{name}: must be positive")
    if nonnegative and number < 0:
        raise ValueError(f"{name}: must be nonnegative")
    return number


def density_archimedes(
    dry_mass_g,
    immersed_mass_g,
    fluid_density_g_cm3,
    *,
    dry_mass_sd_g=None,
    immersed_mass_sd_g=None,
    fluid_density_sd_g_cm3=None,
):
    """Basic two-weighing Archimedes reduction, not an open-pore correction.

    SD propagation assumes independent stated standard uncertainties. Missing inputs
    produce unknown uncertainty, not zero. Operators must confirm method suitability,
    tare/suspension corrections, fluid temperature, wetting and pore-access effects.
    """
    dry = finite(dry_mass_g, "dry_mass_g", positive=True)
    immersed = finite(immersed_mass_g, "immersed_mass_g")
    fluid = finite(fluid_density_g_cm3, "fluid_density_g_cm3", positive=True)
    delta = dry - immersed
    if delta <= 0:
        raise ValueError("dry mass must exceed immersed apparent mass")
    density = fluid * dry / delta
    terms = (dry_mass_sd_g, immersed_mass_sd_g, fluid_density_sd_g_cm3)
    for index, value in enumerate(terms):
        if value is not None:
            finite(value, f"uncertainty_{index}", nonnegative=True)
    sd = None
    if all(value is not None for value in terms):
        a, b, c = (float(value) for value in terms)
        sd = math.sqrt(
            (-fluid * immersed / delta**2 * a) ** 2
            + (fluid * dry / delta**2 * b) ** 2
            + (dry / delta * c) ** 2
        )
    return {
        "quantity": "density_g_cm3",
        "value": density,
        "unit": "g/cm^3",
        "uncertainty": sd,
        "method": "two_weighing_archimedes",
        "status": "derived",
        "statistical_unit": "specimen",
        "measurement_population": "bulk_specimen",
        "measurement_statistic": "density",
        "uncertainty_basis": "independent_input_standard_uncertainties",
        "inputs": {
            "dry_mass_g": dry, "immersed_mass_g": immersed, "fluid_density_g_cm3": fluid,
            "dry_mass_sd_g": dry_mass_sd_g, "immersed_mass_sd_g": immersed_mass_sd_g,
            "fluid_density_sd_g_cm3": fluid_density_sd_g_cm3,
        },
        "limits": [
            "No inferred calibration, air-buoyancy or open-pore correction",
            "Wetting, fluid temperature, suspension and specimen integrity require review",
        ],
    }


def relative_density(density_g_cm3, reference_density_g_cm3, *, density_sd=None, reference_sd=None):
    density = finite(density_g_cm3, "density_g_cm3", positive=True)
    reference = finite(reference_density_g_cm3, "reference_density_g_cm3", positive=True)
    for value in (density_sd, reference_sd):
        if value is not None:
            finite(value, "standard uncertainty", nonnegative=True)
    sd = None
    if density_sd is not None and reference_sd is not None:
        sd = math.hypot(float(density_sd) / reference, density * float(reference_sd) / reference**2)
    return {
        "quantity": "relative_density",
        "value": density / reference,
        "unit": "1",
        "uncertainty": sd,
        "status": "derived",
        "reference_density_g_cm3": reference,
        "warning": "Reference must be justified for this composition; no clipping at one",
    }


def read_sps_csv(path):
    """Read a normalized export; vendor conversion must remain separately recorded.

    Exact units are encoded in columns. Blank readbacks remain null. A trace records
    sensor readings; its temperature column is not necessarily sample temperature.
    """
    columns = ("temperature_C", "pressure_MPa", "displacement_mm")
    records = []
    with Path(path).open(newline="", encoding="utf-8-sig") as handle:
        reader = csv.DictReader(handle)
        if not reader.fieldnames or "time_s" not in reader.fieldnames:
            raise ValueError("SPS export requires time_s with explicit seconds")
        if not any(column in reader.fieldnames for column in columns):
            raise ValueError("SPS export contains no supported readback columns")
        for index, row in enumerate(reader):
            if None in row:
                raise ValueError(f"SPS row {index}: unexpected extra columns")
            time = finite(row.get("time_s"), "time_s", nonnegative=True)
            if records and time <= records[-1]["time_s"]:
                raise ValueError(
                    "SPS time must strictly increase; reconcile duplicate/reset clocks"
                )
            record = {"time_s": time}
            for column in columns:
                text = row.get(column)
                record[column] = None if text is None or not text.strip() else finite(text, column)
            records.append(record)
    if not records:
        raise ValueError("empty SPS export")
    summary = {}
    for column in columns:
        values = [record[column] for record in records if record[column] is not None]
        summary[column] = {
            "available_count": len(values),
            "missing_count": len(records) - len(values),
            "minimum": min(values) if values else None,
            "maximum": max(values) if values else None,
        }
    return {
        "records": records,
        "summary": summary,
        "duration_s": records[-1]["time_s"] - records[0]["time_s"],
        "warnings": [
            "Sensor position/calibration and tooling require separate metadata",
            "Punch displacement includes tooling response, not just specimen shrinkage",
            "Missing readings were not interpolated or replaced by setpoints",
        ],
    }


def microscopy_observations(record, *, source_file):
    """Reduce operator/algorithm-resolved features without inventing SEM images.

    Field/section identities and source image links remain mandatory. Feature sample
    SD is not specimen-to-specimen or mean-estimate uncertainty.
    """
    for name in ("specimen_id", "section_id", "field_id", "method"):
        if not isinstance(record.get(name), str) or not record[name].strip():
            raise ValueError(f"microscopy requires {name}")
    if not source_file:
        raise ValueError("microscopy requires an original image reference")
    common = {name: record[name] for name in ("specimen_id", "section_id", "field_id", "method")}
    common.update(
        source_file=str(source_file),
        status="derived",
        uncertainty=None,
        resolved_grain_boundaries=record.get("grain_boundaries_resolved") is True,
        statistical_unit="field",
        measurement_population=record.get("measurement_population", "selected_field"),
        sampling_plan=record.get("sampling_plan"),
        feature_definition=record.get("feature_definition"),
    )
    observations = []
    if record.get("porosity_area_fraction") is not None:
        porosity = finite(
            record["porosity_area_fraction"], "porosity_area_fraction", nonnegative=True
        )
        if porosity > 1:
            raise ValueError("porosity area fraction exceeds one")
        observations.append(
            {
                **common,
                "quantity": "porosity_area_fraction",
                "value": porosity,
                "unit": "1",
                "limits": ["2D selected field, not bulk porosity"],
            }
        )
    grains = record.get("grain_sizes_nm")
    if record.get("grain_boundaries_resolved") is not True:
        if grains:
            raise ValueError("grain sizes provided without resolved grain boundaries")
        observations.append(
            {
                **common,
                "quantity": "grain_size_nm",
                "value": None,
                "unit": "nm",
                "status": "unavailable",
                "limits": ["Grain boundaries not resolved; no grain-growth claim"],
            }
        )
    elif grains:
        finite(record.get("scale_nm_per_pixel"), "scale_nm_per_pixel", positive=True)
        sizes = [finite(value, "grain_size_nm", positive=True) for value in grains]
        observations.append(
            {
                **common,
                "quantity": "grain_size_nm",
                "value": mean(sizes),
                "unit": "nm",
                "median_nm": median(sizes),
                "feature_count": len(sizes),
                "feature_sample_sd_nm": stdev(sizes) if len(sizes) > 1 else None,
                "measurement_statistic": "number_mean",
                "grain_sizes_nm": sizes,
                "distribution": grain_distribution(
                    sizes, coarse_threshold_nm=record["coarse_threshold_nm"]
                ) if record.get("coarse_threshold_nm") is not None else None,
                "limits": [
                    "Features nested within one selected field/specimen",
                    "A starting-state comparator is needed for grain growth",
                ],
            }
        )
    else:
        raise ValueError("resolved grain boundaries require actual measured feature sizes")
    return observations


def microscopy_specimen_observations(records, *, coarse_threshold_nm):
    """Aggregate measured fields from one specimen, retaining all source records.

    Grain features are number weighted; porosity is weighted by imaged field area.
    These are descriptors of selected sections, not independent specimen repeats
    or unbiased estimates of bulk structure. No statistical uncertainty is inferred.
    """
    if not isinstance(records, list) or not records or any(
        not isinstance(record, dict) for record in records
    ):
        raise ValueError("microscopy aggregation requires actual field records")
    threshold = finite(coarse_threshold_nm, "coarse_threshold_nm", positive=True)
    identities, sources, features, porosity_fields = set(), set(), [], []
    first = records[0]
    shared = ("specimen_id", "method", "sampling_plan", "feature_definition")
    for record in records:
        for key in (*shared, "section_id", "field_id", "source_file"):
            if not isinstance(record.get(key), str) or not record[key].strip():
                raise ValueError(f"microscopy aggregation requires explicit {key}")
        if any(record[key] != first[key] for key in shared):
            raise ValueError("mixed specimens or inconsistent method, sampling plan or feature definition")
        identity = (record["section_id"], record["field_id"])
        if identity in identities or record["source_file"] in sources:
            raise ValueError("duplicated microscopy field or original image reference")
        identities.add(identity)
        sources.add(record["source_file"])
        if record.get("coarse_threshold_nm", threshold) != threshold:
            raise ValueError("inconsistent coarse threshold")
        if record.get("grain_sizes_nm") is not None and not isinstance(
            record["grain_sizes_nm"], list
        ):
            raise ValueError("grain_sizes_nm must be a measured feature list")
        # Reuse field-level input validation before pooling any descriptors.
        microscopy_observations(record, source_file=record["source_file"])
        grains = record.get("grain_sizes_nm") or []
        if grains:
            ids = record.get("feature_ids")
            if (
                not isinstance(ids, list)
                or len(ids) != len(grains)
                or any(not isinstance(x, str) or not x.strip() for x in ids)
                or len(set(ids)) != len(ids)
            ):
                raise ValueError("each measured grain requires a unique field-scoped feature_id")
            features.extend(finite(x, "grain_size_nm", positive=True) for x in grains)
        if record.get("porosity_area_fraction") is not None:
            area = finite(record.get("field_area_um2"), "field_area_um2", positive=True)
            porosity_fields.append((identity, area, float(record["porosity_area_fraction"])))
    resolved = all(record.get("grain_boundaries_resolved") is True for record in records)
    common = {
        **{key: first[key] for key in shared},
        "status": "derived",
        "statistical_unit": "specimen",
        "measurement_population": "selected_sections",
        "uncertainty": None,
        "uncertainty_basis": "not_estimated",
        "resolved_grain_boundaries": resolved,
        "field_count": len(records),
        "section_ids": sorted({r["section_id"] for r in records}),
        "field_identities": [
            {"section_id": r["section_id"], "field_id": r["field_id"]} for r in records
        ],
        "source_files": [r["source_file"] for r in records],
        "raw_field_records": deepcopy(records),
        "limits": [
            "Selected 2D sections, not bulk or volume-weighted microstructure",
            "Features and fields are nested within one specimen, not independent specimens",
            "Sampling and segmentation bias and predictive uncertainty remain unknown",
            "Grain descriptors do not establish boundary chemistry or magnetic performance",
        ],
    }
    observations = []
    if features and resolved:
        distribution = grain_distribution(features, coarse_threshold_nm=threshold)
        for quantity, statistic, key, unit in (
            ("grain_size_nm", "number_mean", "mean_nm", "nm"),
            ("grain_d90_nm", "d90", "d90_nm", "nm"),
            ("coarse_number_fraction", "coarse_number_fraction", "coarse_number_fraction", "1"),
        ):
            observations.append({
                **deepcopy(common), "quantity": quantity, "value": distribution[key],
                "unit": unit, "measurement_statistic": statistic, "weighting": "number",
                "coarse_threshold_nm": threshold, "distribution": deepcopy(distribution),
            })
    else:
        observations.append({
            **deepcopy(common), "quantity": "grain_size_nm", "value": None,
            "unit": "nm", "status": "unavailable", "measurement_statistic": "number_mean",
            "reason": "Not all selected fields have resolved grain features; no aggregate inferred",
        })
    if porosity_fields:
        area = sum(item[1] for item in porosity_fields)
        observations.append({
            **deepcopy(common), "quantity": "porosity_area_fraction", "unit": "1",
            "value": sum(a * fraction for _, a, fraction in porosity_fields) / area,
            "measurement_statistic": "area_fraction", "weighting": "imaged_area",
            "measured_area_um2": area,
            "porosity_field_identities": [
                {"section_id": identity[0], "field_id": identity[1]}
                for identity, _, _ in porosity_fields
            ],
            "porosity_missing_field_count": len(records) - len(porosity_fields),
        })
    return observations


def review_reduction(observation, *, decision, reviewer, rationale):
    """Record quality review without releasing evidence or changing its provenance.

    Reviewer identity is an operator assertion, not authentication. Campaign custody
    and evidence release remain separate. A review never promotes unavailable data.
    """
    if decision not in {"accepted", "rejected"}:
        raise ValueError("review decision must be accepted or rejected")
    if any(not isinstance(x, str) or not x.strip() for x in (reviewer, rationale)):
        raise ValueError("reduction review requires reviewer and rationale")
    if not isinstance(observation, dict) or observation.get("status") != "derived":
        raise ValueError("quality review requires a derived observation")
    finite(observation.get("value"), "derived observation value")
    if not any(observation.get(key) for key in ("inputs", "raw_field_records", "source_file")):
        raise ValueError("reduction review requires preserved input provenance")
    result = deepcopy(observation)
    review = {"decision": decision, "reviewer": reviewer.strip(), "rationale": rationale.strip()}
    result.setdefault("review_history", []).append(deepcopy(review))
    result["quality_review"] = review
    return result


def particle_size_percentiles(d10_um, d50_um, d90_um, *, method, sample_id):
    values = [
        finite(value, name, positive=True)
        for value, name in zip(
            (d10_um, d50_um, d90_um), ("d10_um", "d50_um", "d90_um"), strict=True
        )
    ]
    if values != sorted(values):
        raise ValueError("particle size percentiles must be ordered")
    if not method or not sample_id:
        raise ValueError("particle size requires method and sampled powder identity")
    return {
        "sample_id": sample_id,
        "sample_kind": "powder",
        "method": method,
        "d10_um": values[0],
        "d50_um": values[1],
        "d90_um": values[2],
        "uncertainty": None,
        "warning": "Particle size is not grain size",
    }
